class Solution {
public:
    bool possibleToStamp(vector<vector<int>>& grid, int h, int w) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<char>> covered(m, vector<char>(n, 0));
        for (int r = 0; r + h <= m; r++) {
            for (int c = 0; c + w <= n; c++) {
                bool clean = true;
                for (int i = r; i < r + h && clean; i++)
                    for (int j = c; j < c + w && clean; j++)
                        if (grid[i][j]) clean = false;
                if (!clean) continue;
                for (int i = r; i < r + h; i++)
                    for (int j = c; j < c + w; j++)
                        covered[i][j] = 1;
            }
        }
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (!grid[i][j] && !covered[i][j]) return false;
        return true;
    }
};

