class Solution:
    def possibleToStamp(self, grid: List[List[int]], h: int, w: int) -> bool:
        m, n = len(grid), len(grid[0])
        P = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m):
            for j in range(n):
                P[i + 1][j + 1] = (P[i][j + 1] + P[i + 1][j]
                                   - P[i][j] + grid[i][j])

        D = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(h - 1, m):
            for j in range(w - 1, n):
                s = (P[i + 1][j + 1] - P[i - h + 1][j + 1]
                     - P[i + 1][j - w + 1] + P[i - h + 1][j - w + 1])
                if s == 0:
                    D[i - h + 1][j - w + 1] += 1
                    D[i + 1][j - w + 1] -= 1
                    D[i - h + 1][j + 1] -= 1
                    D[i + 1][j + 1] += 1

        for i in range(m):
            for j in range(n):
                D[i][j] += ((D[i - 1][j] if i else 0)
                            + (D[i][j - 1] if j else 0)
                            - (D[i - 1][j - 1] if i and j else 0))
                if grid[i][j] == 0 and D[i][j] == 0:
                    return False
        return True

