class Solution {
public:
    bool possibleToStamp(vector<vector<int>>& grid, int h, int w) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<long long>> P(m + 1, vector<long long>(n + 1, 0));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                P[i + 1][j + 1] = P[i][j + 1] + P[i + 1][j] - P[i][j] + grid[i][j];

        vector<vector<int>> D(m + 1, vector<int>(n + 1, 0));
        for (int i = h - 1; i < m; i++)
            for (int j = w - 1; j < n; j++) {
                long long s = P[i + 1][j + 1] - P[i - h + 1][j + 1]
                            - P[i + 1][j - w + 1] + P[i - h + 1][j - w + 1];
                if (s == 0) {
                    D[i - h + 1][j - w + 1]++;
                    D[i + 1][j - w + 1]--;
                    D[i - h + 1][j + 1]--;
                    D[i + 1][j + 1]++;
                }
            }

        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                D[i][j] += (i ? D[i - 1][j] : 0) + (j ? D[i][j - 1] : 0)
                         - (i && j ? D[i - 1][j - 1] : 0);
                if (!grid[i][j] && D[i][j] == 0) return false;
            }
        return true;
    }
};

