                        - P[i + 1][j - w + 1] + P[i - h + 1][j - w + 1] == 0) {
                    D[i - h + 1][j - w + 1]++;
                    D[i + 1][j - w + 1]--;
                    D[i - h + 1][j + 1]--;
                    D[i + 1][j + 1]++;
